mapper.select:
SELECT TRIM(br.behavior_description) AS description, COUNT(*) AS count
FROM behavior_record br
JOIN class_record cr ON cr.id = br.class_record_id
WHERE cr.student_id = #{studentId}
  AND cr.record_date BETWEEN #{start} AND #{end}
  AND br.detail_saved = TRUE
  AND NULLIF(TRIM(br.behavior_description), '') IS NOT NULL
GROUP BY TRIM(br.behavior_description)
ORDER BY count DESC, description
LIMIT #{limit}

SELECT TRIM(br.behavior_description) AS description, cr.record_date AS date, COUNT(*) AS count
FROM behavior_record br
JOIN class_record cr ON cr.id = br.class_record_id
WHERE cr.student_id = #{studentId}
  AND cr.record_date BETWEEN #{start} AND #{end}
  AND br.detail_saved = TRUE
  AND TRIM(br.behavior_description) IN

    #{description}

GROUP BY TRIM(br.behavior_description), cr.record_date
ORDER BY description, cr.record_date
